/// lookup 索引 -> 字符串，按索引升序，供二分查找。
pub static LOOKUP: &[(u32, &str)] = &[
];

/// 二分查找 token 对应的字段名。
pub fn resolve(token: u16) -> Option<&'static str> {
    TOKENS.binary_search_by_key(&token, |(t, _)| *t)
        .ok()
        .map(|i| TOKENS[i].1)
}

/// 二分查找 lookup 索引对应的字符串。
pub fn lookup(index: u32) -> Option<&'static str> {
    LOOKUP.binary_search_by_key(&index, |(i, _)| *i)
        .ok()
        .map(|i| LOOKUP[i].1)
}
